#!/usr/bin/env python3
"""Generate a C++ program that dumps sizeof/offsetof for every CTP struct."""

from __future__ import annotations

import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parents[1] / "ctpgen"))
from parse_ctp import DEFAULT_API_DIR, load  # noqa: E402

OUT = Path(__file__).resolve().parent / "build" / "layout_dump.cpp"


def main() -> int:
    _, structs = load()
    lines = [
        "// generated by tools/layout-check/gen_layout_cpp.py",
        "#include <cstdio>",
        "#include <cstddef>",
        '#include "ThostFtdcUserApiStruct.h"',
        "",
        "int main() {",
    ]
    for s in structs.values():
        cname = "C" + s.name
        lines.append(f'    std::printf("S|{s.name}|%zu\\n", sizeof({cname}));')
        for f in s.fields:
            lines.append(
                f'    std::printf("F|{s.name}|{f.name}|%zu\\n", offsetof({cname}, {f.name}));'
            )
    lines.append("    return 0;")
    lines.append("}")
    OUT.parent.mkdir(parents=True, exist_ok=True)
    OUT.write_text("\n".join(lines) + "\n", encoding="utf-8")
    print(f"generated {OUT} ({len(structs)} structs)")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
